:is(.avatar-user, .avatar.circle, [data-component="Avatar"], .AppHeader-user, .AppHeader-user img, .AvatarStack-body, .State, .state, [data-component="StateLabel"]) {
    border-radius: 6px !important;
  }
  .avatar:not(.avatar-user, .circle), [data-component="Avatar"][data-square] {
    border-radius: 0 !important;
  }
  :is(.IssueLabel, [style*="--label-r:"], .Label, .label, [data-component="Label"], .Counter, .counter, [data-component="CounterLabel"], .signed-commit-badge, .topic-tag, .topic-tag-action, .delete-topic-button, a[href^="/topics/"]:not(:has(img))),
  :is(.avatar-user, .avatar.circle, [data-component="Avatar"])[width="20"]:not([data-square]),
  .AvatarStack .avatar-user:has(> img[width="20"]) {
    border-radius: 4px !important;
  }
  [data-component="AvatarStack"] [data-component="Avatar"] {
    mask-image: none !important;
  }
